package tk103

import (
	"strings"
	"testing"

	"github.com/DATASMARTCOMCORP/traccar-api-java/server-go/internal/ingest"
	"github.com/DATASMARTCOMCORP/traccar-api-java/server-go/internal/protocol/kit"
	"github.com/DATASMARTCOMCORP/traccar-api-java/server-go/internal/protocol/oracle"
)

func TestJavaDecoder(t *testing.T) {
	oracle.Run(t, "Tk103ProtocolDecoderTest", oracle.Handlers{
		Decoder: func(string, *oracle.Env) ingest.Decoder { return &Decoder{} },
	})
}

func TestJavaEncoder(t *testing.T) {
	oracle.Run(t, "Tk103ProtocolEncoderTest", oracle.Handlers{
		Encoder: func(method string, _ ingest.Decoder) ingest.CommandEncoder {
			return &Encoder{ForceAlternative: strings.HasSuffix(method, "Alternative")}
		},
	})
}

// Tk103FrameDecoderTest compares with assertEquals, so it has no recorded calls; its
// cases are checked here, decoding the same buffer again as the Java test does.
func TestFramer(t *testing.T) {
	f := Framer()
	m := oracle.NewEnv().Message(oracle.Record{})
	frame := func(buf *kit.Buf) string {
		if got, ok := f.Frame(m, buf).(*kit.Buf); ok {
			return got.HexDump()
		}
		return ""
	}
	check := func(want, got string) {
		t.Helper()
		if strings.ToLower(want) != got {
			t.Fatalf("frame %s, want %s", got, want)
		}
	}

	check("283836343735353535353535353535352C445733422C3133313131372C412C353536322E30323837304E2C30313334382E3038313934452C312E3539372C3232333730372C3239312E36352C2D302E31302C3429",
		frame(kit.Hex("283836343735353535353535353535352C445733422C3133313131372C412C353536322E30323837304E2C30313334382E3038313934452C312E3539372C3232333730372C3239312E36352C2D302E31302C3429283836343735353535353535353535352C5A4332302C3133313131372C3232333730362C362C3339342C36353533352C32353529")))

	buf := kit.Hex("")
	check("", frame(buf))
	check("283836343735353535353535353535352C5A4332302C3133313131372C3232333730362C362C3339342C36353533352C32353529", frame(buf))

	check("283836343735353535353535353535352C445733422C3133313131372C412C353536322E30323837304E2C30313334382E3038313934452C312E3539372C3232333730372C3239312E36352C2D302E31302C3429",
		frame(kit.Hex("")))

	check("", frame(kit.Hex("67")))
	check("", frame(kit.Hex("676172626167652540232a5e242d2b3c3e3f24")))

	check("2838363437353535353535352C5A4330332C3139313131372C3233343432312C24294E6F746963653A0D0A446576696365732073657269616C206E756D6265723A200D0A3538303535353535353535292E0D0A536F6674776172652076657273696F6E3A0D0A56322E3030302C323031362F30382F32332031313A3137292429",
		frame(kit.Hex("")))

	check("", frame(kit.Hex("")))
}
